-- Alcohol products of the Mikes menu (toujoursmikes.ca): a "Bar" group for both restaurants. Beers in the back store (draft in the fridge), wines in the cellar; Molson for beers, SAQ for wines.
INSERT INTO ingredient_groups (restaurant_id, name_fr, name_en, post_id, position) SELECT r.id, 'Bar', 'Bar', NULL, COALESCE((SELECT MAX(position) FROM ingredient_groups WHERE restaurant_id = r.id), 0) + 1 FROM restaurants r WHERE (r.name LIKE '%Sauveur%' OR r.name LIKE '%Agathe%') AND NOT EXISTS (SELECT 1 FROM ingredient_groups g WHERE g.restaurant_id = r.id AND g.name_fr = 'Bar');
INSERT INTO ingredients (group_id, name, location, category, position) SELECT g.id, 'Molson Canadian (canette 473 ml)', 'backstore', 'beers', COALESCE((SELECT MAX(i.position) FROM ingredients i WHERE i.group_id = g.id), 0) + 1 FROM ingredient_groups g JOIN restaurants r ON r.id = g.restaurant_id WHERE g.name_fr = 'Bar' AND (r.name LIKE '%Sauveur%' OR r.name LIKE '%Agathe%') AND NOT EXISTS (SELECT 1 FROM ingredients i WHERE i.group_id = g.id AND i.name = 'Molson Canadian (canette 473 ml)');
INSERT OR IGNORE INTO ingredient_suppliers (ingredient_id, supplier_id) SELECT i.id, s.id FROM ingredients i JOIN ingredient_groups g ON g.id = i.group_id JOIN restaurants r ON r.id = g.restaurant_id JOIN suppliers s ON s.client_id = r.client_id AND s.name LIKE 'Molson%' WHERE g.name_fr = 'Bar' AND i.name = 'Molson Canadian (canette 473 ml)';
